-- Il confronto è sul nome normalizzato: maiuscole e punteggiatura non fanno due
-- società diverse.
insert into public.contacts (kind, company_name, address, vat_number, country)
select 'client', n.nome, nullif(n.indirizzo,''), nullif(n.piva,''), nullif(n.paese,'')
  from clienti_nuovi n
 where not exists (
   select 1 from public.contacts c
    where c.kind = 'client'
      and lower(btrim(regexp_replace(translate(c.company_name,'–—’','--'''),'[^a-zA-Z0-9]+',' ','g')))
        = lower(btrim(regexp_replace(translate(n.nome,'–—’','--'''),'[^a-zA-Z0-9]+',' ','g')))
 );

select
  (select count(*) from clienti_nuovi) as letti_dai_documenti,
  (select count(*) from public.contacts where kind='client') as clienti_in_anagrafica;
